command:
let actors = game.actors;

let html = `<h2>${game.i18n.localize("UTCF.Roll.Label")} ${game.i18n.localize("UTCF.Fortune.Label")}</h2><form><div class="form-field"><label>Actor</label><select name="actor_id">`;

actors.forEach(actor => {
  html += `<option value="${actor.id}">${actor.name}</option>`
});

html += `</select></div></form>`;

new foundry.applications.api.DialogV2({
      window: {
        contentClasses: ["until-the-curtain-falls", "dialog-window"],
        title: `${game.i18n.localize("UTCF.Roll.Label")} ${game.i18n.localize("UTCF.Fortune.Label")}`
      },
      content: html,
      buttons: [
        {
          icon: '<i class="fas fa-check"></i>',
          label: game.i18n.localize('Roll'),
          action: 'add',
          callback: async (event, button, dialog) => {
            let actor_id = button.form.elements.actor_id.value;
            let actor = game.actors.get(actor_id);
            actor.rollFortuneDialog();
          }
        },
        {
          icon: '<i class="fas fa-times"></i>',
          label: game.i18n.localize('Cancel'),
          action: 'cancel',
          callback: () => false
        }
      ]
    }, {}).render({force: true});
